sys_variable_value.value:
(function execute(inputs, outputs) {
    var reservedFor = inputs.reserved_for ? 
        inputs.reserved_for.getDisplayValue() : 'Unknown';
    var workspace = inputs.workspace ? 
        inputs.workspace.getDisplayValue() : 'Unknown';
    var startDate = inputs.start_date_time ? 
        inputs.start_date_time + '' : 'Unknown';

    var message = '✅ Workspace reservation approved!\n' +
        '👤 Reserved for: ' + reservedFor + '\n' +
        '🏢 Workspace: ' + workspace + '\n' +
        '📅 Start: ' + startDate;

    var discord = new discordNotification();
    discord.sendMessage(message, '');
})(inputs, outputs);

